package com.simon.voiceime;
import java.io.*;import java.util.*;import org.junit.*;import static org.junit.Assert.*;
public class App690ERecordsTest {
 DualHandTracks tracks;
 @Before public void load()throws Exception {tracks=new DualHandTracks(new FileReader("src/phone/assets/dual_hand/phrase_words.tsv"),new FileReader("src/phone/assets/dual_hand/grid_chars.tsv"),new FileReader("src/phone/assets/dual_hand/readings.tsv"));}
 @Test public void bankUsesExactReadingAndVoiceReverseLookup(){CorrectionRecords r=new CorrectionRecords();r.record(0,"銀行",Arrays.asList("ㄧㄣˊ","ㄏㄤˊ"),tracks,false);assertEquals("ㄧㄣ",r.reading(0,"銀"));assertEquals("ㄏㄤ",r.reading(1,"行"));List<DualHandTracks.Choice> exact=tracks.grid(Arrays.asList(tracks.readings("銀"),Collections.singletonList(r.reading(1,"行"))),1);assertFalse(exact.stream().anyMatch(c->c.text.equals("星")));assertEquals(Arrays.asList("ㄏㄤ","ㄒㄧㄥ"),tracks.readings("行"));List<DualHandTracks.Choice> reverse=tracks.grid(Arrays.asList(tracks.readings("銀"),tracks.readings("行")),1);assertTrue(reverse.stream().anyMatch(c->c.text.equals("星")));}
 @Test public void invalidReadingOrCardinalityCannotBeStored(){CorrectionRecords r=new CorrectionRecords();r.record(0,"銀行",Arrays.asList("ㄧㄣ","ㄅㄚ"),tracks,false);assertEquals(1,r.size());assertNull(r.reading(1,"行"));r.clear();r.record(0,"銀行",Collections.singletonList("ㄧㄣ"),tracks,false);assertEquals(0,r.size());}
 @Test public void invalidNewCommitCannotReuseAnOlderReading(){CorrectionRecords r=new CorrectionRecords();r.record(0,"銀行",Arrays.asList("ㄧㄣ","ㄏㄤ"),tracks,false);r.record(0,"銀行",Collections.singletonList("ㄧㄣ"),tracks,false);assertNull(r.reading(1,"行"));assertEquals(0,r.size());}
 @Test public void partialCommitHasOnlyActualCharacters(){Object controller=new Object();CorrectionCommitRecord.capture(controller,"銀",Arrays.asList("ㄧㄣˊ","ㄏㄤˊ"),1);assertEquals(Collections.singletonList("ㄧㄣ"),CorrectionCommitRecord.take(controller,"銀"));assertNull(CorrectionCommitRecord.take(controller,"银"));}
 @Test public void rebaseInsertionAndReplacementInvalidateOnlyChangedGlyph(){CorrectionRecords r=new CorrectionRecords();r.record(0,"銀行",Arrays.asList("ㄧㄣ","ㄏㄤ"),tracks,false);r.rebase("銀行","甲銀行",0,0,"甲");assertEquals("ㄏㄤ",r.reading(2,"行"));assertNull(r.reading(2,"星"));r.rebase("甲銀行","甲銀星",2,3,"星");assertNull(r.reading(2,"星"));assertEquals("ㄧㄣ",r.reading(1,"銀"));}
 @Test public void oldestRecordsAreEvictedAndPasswordClears(){CorrectionRecords r=new CorrectionRecords();r.record(0,"銀".repeat(2001),Collections.nCopies(2001,"ㄧㄣ"),tracks,false);assertEquals(2000,r.size());assertNull(r.reading(0,"銀"));assertEquals("ㄧㄣ",r.reading(2000,"銀"));r.record(0,"銀",Collections.singletonList("ㄧㄣ"),tracks,true);assertEquals(0,r.size());}
 @Test public void positionMatchesHandComputed6891Thresholds(){float density=1;int[][] input={{19,49},{20,50},{21,51},{27,57},{28,58},{29,59}};int[] want={45,0,1,7,8,9};for(int i=0;i<input.length;i++)assertArrayEquals(new int[]{84,want[i]},CorrectionPosition.place(100,input[i][0],input[i][1],32,24,400,0,800,density));assertArrayEquals(new int[]{0,80},CorrectionPosition.place(-10,100,130,32,24,400,0,800,1));assertArrayEquals(new int[]{368,80},CorrectionPosition.place(500,100,130,32,24,400,0,800,1));}
 @Test public void cancelledGridCountsWithoutAnyUserText(){CorrectionCounters c=new CorrectionCounters();c.open("voice");c.cancel();assertEquals(1,c.count("voice","opened"));assertEquals(1,c.count("voice","cancelled"));c.open("bopomofo");c.choose(4);c.cancel();assertEquals(0,c.count("bopomofo","cancelled"));assertEquals(1,c.count("bopomofo","chosen_4"));assertFalse(c.snapshot().toString().contains("銀行"));}
 @Test public void learningOnlyWritesDualHandMemory()throws Exception {File dir=new File(System.getProperty("java.io.tmpdir"),"app690e-learning");dir.mkdirs();File rime=new File(dir,"rime-user.tsv"),personal=new File(dir,"dual_hand_personal.tsv");java.nio.file.Files.write(rime.toPath(),"unchanged".getBytes(java.nio.charset.StandardCharsets.UTF_8));byte[] before=java.nio.file.Files.readAllBytes(rime.toPath());DualHandMemory memory=new DualHandMemory(personal);long count=memory.find(Collections.singletonList("ㄏㄤ")).stream().filter(e->e.text.equals("行")).mapToLong(e->e.count).sum();memory.remember(Collections.singletonList("ㄏㄤ"),"行",false);assertEquals(count+1,memory.find(Collections.singletonList("ㄏㄤ")).stream().filter(e->e.text.equals("行")).mapToLong(e->e.count).sum());assertArrayEquals(before,java.nio.file.Files.readAllBytes(rime.toPath()));assertFalse(memory.remember(Collections.singletonList("ㄏㄤ"),"行",true));}
}
